# Publishes a release that is already bumped (bump-version.ps1) and built (build-release.ps1):
# commits the version files, pushes, tags, makes the GitHub release, then commits the package copies of
# README and CHANGELOG as a separate commit (Package\README.md is generated by the Release build).
# Usage: .\tools\publishing\release.ps1 -Title "lighter and faster"
param([Parameter(Mandatory = $true)][string]$Title)
$ErrorActionPreference = 'Continue'
$root = Resolve-Path (Join-Path $PSScriptRoot '..\..')
Set-Location $root

$plugin = [IO.File]::ReadAllText("$root\BrudvikWhiteHilt\BrudvikWhiteHilt.cs")
$version = [regex]::Match($plugin, 'PluginVersion = "([0-9.]+)"').Groups[1].Value
if (-not $version) { throw 'PluginVersion not found' }

# The commit messages go through files, as PowerShell has no heredoc and git -m mangles quotes.
$message = Join-Path ([IO.Path]::GetTempPath()) "wh_release_msg_$version.txt"
$utf8 = New-Object Text.UTF8Encoding $false

[IO.File]::WriteAllText($message, "Release v${version}: $Title`n", $utf8)
git add BrudvikWhiteHilt/BrudvikWhiteHilt.cs BrudvikWhiteHilt/Package/manifest.json BrudvikWhiteHilt/Properties/AssemblyInfo.cs CHANGELOG.md README.MD
git commit "--file=$message"
$sha = (git rev-parse HEAD).Trim()
git push origin master
if ($LASTEXITCODE -ne 0) { throw 'push failed' }
git tag -a "v$version" -m "BrudvikWhiteHilt v$version" $sha
git push origin "v$version"
if ($LASTEXITCODE -ne 0) { throw 'tag push failed' }
& (Join-Path $PSScriptRoot 'github-release.ps1') -Tag "v$version"

[IO.File]::WriteAllText($message, "Package: release notes for v$version`n", $utf8)
git add BrudvikWhiteHilt/Package/README.md BrudvikWhiteHilt/Package/CHANGELOG.md
git commit "--file=$message"
git push origin master
git status --short
git log --oneline -4
